def chain_chain(chain):
    chain = list(chain)
    chain.sort(key=lambda x: (x[0], x[1]))
    result = []
    for i in range(len(chain)):
        if i == 0:
            result.append(chain[i][1])
        else:
            if chain[i][0] == chain[i-1][1]:
                result.append(chain[i][1])
            else:
                result.append(chain[i][0])
    return ','.join(result)

